#include "EditorFeedSequence.h"
#include <array>
#include <cstring>
#include <stdexcept>
#include <cstdio>
using namespace Frontier;using namespace Frontier::HostRuntime;
static unsigned Checks=0;static void Check(bool V,const char* N){++Checks;if(!V)throw std::runtime_error(N);}static EditorProperty* Find(EditorSheet& S,const char* N){for(uint32_t G=0;G<S.GroupCount;++G)for(uint32_t I=0;I<S.Groups[G].PropertyCount;++I)if(!std::strcmp(S.Groups[G].Properties[I].Label,N))return &S.Groups[G].Properties[I];return nullptr;}
int main(){SceneStructure World;ConstructRequest R;R.Kind=ConstructKind::SpotLight;R.Name="Key Spot";R.Position[0]=2;R.Position[1]=3;R.Position[2]=4;auto Made=ConstructEntity(World,R);Check(bool(Made),"spot creation");std::array<EditorInstance,kMaxEditorInstances> Rows{};EditorFeedSequence Feed;uint32_t Count=Feed.FillRoster(Rows.data(),World);uint32_t Pick=0;while(Pick<Count&&std::strcmp(Rows[Pick].Label,"Key Spot"))++Pick;Check(Pick<Count&&Rows[Pick].Category==EditorInstanceCategory::Light,"outliner light row");Check(std::strstr(Rows[Pick].Meta,"Spot")&&std::strstr(Rows[Pick].Meta,"cd"),"light metadata");EditorSheet Sheet;FlyThroughSolver Camera;(void)Feed.BuildSheet(Pick,Rows.data(),Count,&Sheet,Camera,World,World.QueryInstances());Check(Sheet.Appearance==EditorSheetAppearance::Light,"dedicated light sheet");Find(Sheet,"Intensity")->Figure=2400;Find(Sheet,"Range")->Figure=42;Find(Sheet,"Position")->Axes[0]=9;Find(Sheet,"Distribution")->Picked=uint32_t(LuminaireDistribution::AutomotiveLowBeam);Feed.ApplyLightSheet(Pick,Count,World,Sheet);const auto& L=World.QueryPunctualLuminaires()[0];Check(L.Intensity==2400&&L.Range==42,"light scalar writeback");Check(L.Distribution==LuminaireDistribution::AutomotiveLowBeam,"distribution writeback");Check(World.QueryPlacements()[Made.Placement].WorldTransform[12]==9,"transform writeback");(void)Feed.BuildSheet(Pick,Rows.data(),Count,&Sheet,Camera,World,World.QueryInstances());Check(Find(Sheet,"Intensity")->Figure==2400&&Find(Sheet,"Position")->Axes[0]==9,"sheet rebuild preserves light edits");ConstructRequest Strip;Strip.Kind=ConstructKind::StripLight;Strip.Name="LED Strip";auto StripMade=ConstructEntity(World,Strip);Check(bool(StripMade),"strip creation");Count=Feed.FillRoster(Rows.data(),World);uint32_t StripPick=0;while(StripPick<Count&&std::strcmp(Rows[StripPick].Label,"LED Strip"))++StripPick;Check(StripPick<Count,"strip outliner row");(void)Feed.BuildSheet(StripPick,Rows.data(),Count,&Sheet,Camera,World,World.QueryInstances());Check(Find(Sheet,"Flux per metre")&&Find(Sheet,"Emitter density")&&Find(Sheet,"Opal diffuser")&&Find(Sheet,"Draw emitter"),"complete strip property cards");Find(Sheet,"Draw emitter")->On=false;Find(Sheet,"Flux per metre")->Figure=1200;Find(Sheet,"Load per metre")->Figure=12;Find(Sheet,"Dimmer")->Figure=.5f;Find(Sheet,"Strip length")->Figure=3;Find(Sheet,"Emitter density")->Figure=120;Find(Sheet,"Supply voltage")->Figure=24;Feed.ApplyLightSheet(StripPick,Count,World,Sheet);const auto& StripRecord=World.QueryPunctualLuminaires().back();Check(StripRecord.LumensPerMetre==1200&&StripRecord.WattsPerMetre==12&&StripRecord.Dimmer==.5f,"strip output writeback");Check(StripRecord.Size[0]==3&&StripRecord.EmittersPerMetre==120&&StripRecord.SupplyVoltage==24&&StripRecord.Intensity==1800&&!StripRecord.DrawEmitter,"strip layout, participation and derived flux writeback");(void)Feed.BuildSheet(StripPick,Rows.data(),Count,&Sheet,Camera,World,World.QueryInstances());Check(Find(Sheet,"Flux per metre")->Figure==1200&&Find(Sheet,"Strip length")->Figure==3,"strip rebuild persistence");uint32_t Post=0;while(Post<Count&&std::strcmp(Rows[Post].Label,"Post Process"))++Post;Check(Post<Count,"post row");(void)Feed.BuildSheet(Post,Rows.data(),Count,&Sheet,Camera,World,World.QueryInstances());Check(Sheet.Appearance==EditorSheetAppearance::PostProcess,"dedicated post sheet");Find(Sheet,"EV Compensation")->Figure=1.25f;Find(Sheet,"Bloom Intensity")->Figure=.3f;Feed.ApplyPostProcessSheet(Sheet);(void)Feed.BuildSheet(Post,Rows.data(),Count,&Sheet,Camera,World,World.QueryInstances());Check(Find(Sheet,"EV Compensation")->Figure==1.25f&&Find(Sheet,"Bloom Intensity")->Figure==.3f,"post writeback survives rebuild");std::printf("PASS %u checks: creation, outliner metadata, native Light/LED Strip writeback and rebuild, electrical/layout persistence, transform, distribution and Post Process session persistence.\n",Checks);}
